WITH comments AS (SELECT d.doc_id, d.author_key, d.posted_by, d.body, d.ref_value, d.tags, d.created_at, d.updated_at, d.ad_mode, d.ad_target, dg.group_id FROM (SELECT doc_id, author_key, posted_by, body, ref_value, tags, created_at, updated_at, ad_mode, ad_target FROM (SELECT doc_id, author_key, posted_by, body, ref_value, tags, created_at, updated_at, ad_mode, ad_target, deleted, row_number() OVER (PARTITION BY doc_id, author_key ORDER BY updated_at DESC) AS rn FROM documents WHERE collection_name = 'comments') WHERE rn = 1 AND deleted = 0) d JOIN (SELECT doc_id, group_id FROM (SELECT doc_id, group_id, deleted, row_number() OVER (PARTITION BY doc_id, group_id ORDER BY updated_at DESC) AS rn FROM doc_groups WHERE group_id IN ('api.localhost/groups/users/c42-c000000/followers', 'api.localhost/groups/users/c42-c000001/followers', 'api.localhost/groups/users/c42-c000002/followers', 'api.localhost/groups/users/c42-c000003/followers', 'api.localhost/groups/users/c42-c000004/followers', 'api.localhost/groups/users/c42-c000005/followers', 'api.localhost/groups/users/c42-c000006/followers', 'api.localhost/groups/users/c42-c000007/followers', 'api.localhost/groups/users/c42-c000008/followers', 'api.localhost/groups/users/c42-c000009/followers', 'api.localhost/groups/users/c42-c000010/followers', 'api.localhost/groups/users/c42-c000011/followers', 'api.localhost/groups/users/c42-c000012/followers', 'api.localhost/groups/users/c42-c000013/followers', 'api.localhost/groups/users/c42-c000014/followers', 'api.localhost/groups/users/c42-c000015/followers', 'api.localhost/groups/users/c42-c000016/followers', 'api.localhost/groups/users/c42-c000017/followers', 'api.localhost/groups/users/c42-c000018/followers', 'api.localhost/groups/users/c42-c000019/followers')) WHERE rn = 1 AND deleted = 0) dg ON d.doc_id = dg.doc_id WHERE d.author_key NOT IN (SELECT user_key FROM (SELECT user_key, blocked_key, deleted, row_number() OVER (PARTITION BY user_key, blocked_key ORDER BY updated_at DESC, deleted DESC) AS rn FROM user_blacklist) WHERE rn = 1 AND deleted = 0 AND blocked_key = 'c42-reader') AND (d.author_key, dg.group_id) NOT IN (SELECT user_key, group_id FROM (SELECT user_key, group_id, blocked_key, deleted, row_number() OVER (PARTITION BY user_key, group_id, blocked_key ORDER BY updated_at DESC, deleted DESC) AS rn FROM group_blacklist) WHERE rn = 1 AND deleted = 0 AND blocked_key = 'c42-reader') AND NOT (d.author_key != 'c42-reader' AND (d.author_key, dg.group_id) IN (SELECT user_key, group_id FROM (SELECT user_key, group_id, sharing_enabled, deleted, row_number() OVER (PARTITION BY user_key, group_id ORDER BY updated_at DESC) AS rn FROM user_group_sharing) WHERE rn = 1 AND deleted = 0 AND sharing_enabled = 0)) AND (d.doc_id, dg.group_id) NOT IN (SELECT doc_id, group_id FROM (SELECT group_id, doc_id, deleted, row_number() OVER (PARTITION BY group_id, doc_id ORDER BY updated_at DESC, deleted DESC) AS rn FROM group_hidden_docs) WHERE rn = 1 AND deleted = 0) AND d.author_key NOT IN (SELECT username FROM (SELECT username, deleted, row_number() OVER (PARTITION BY username ORDER BY updated_at DESC, deleted DESC) AS rn FROM banned_users) WHERE rn = 1 AND deleted = 0)), posts AS (SELECT d.doc_id, d.author_key, d.posted_by, d.body, d.ref_value, d.tags, d.created_at, d.updated_at, d.ad_mode, d.ad_target, dg.group_id FROM (SELECT doc_id, author_key, posted_by, body, ref_value, tags, created_at, updated_at, ad_mode, ad_target FROM (SELECT doc_id, author_key, posted_by, body, ref_value, tags, created_at, updated_at, ad_mode, ad_target, deleted, row_number() OVER (PARTITION BY doc_id, author_key ORDER BY updated_at DESC) AS rn FROM documents WHERE collection_name = 'posts') WHERE rn = 1 AND deleted = 0) d JOIN (SELECT doc_id, group_id FROM (SELECT doc_id, group_id, deleted, row_number() OVER (PARTITION BY doc_id, group_id ORDER BY updated_at DESC) AS rn FROM doc_groups WHERE group_id IN ('api.localhost/groups/users/c42-c000000/followers', 'api.localhost/groups/users/c42-c000001/followers', 'api.localhost/groups/users/c42-c000002/followers', 'api.localhost/groups/users/c42-c000003/followers', 'api.localhost/groups/users/c42-c000004/followers', 'api.localhost/groups/users/c42-c000005/followers', 'api.localhost/groups/users/c42-c000006/followers', 'api.localhost/groups/users/c42-c000007/followers', 'api.localhost/groups/users/c42-c000008/followers', 'api.localhost/groups/users/c42-c000009/followers', 'api.localhost/groups/users/c42-c000010/followers', 'api.localhost/groups/users/c42-c000011/followers', 'api.localhost/groups/users/c42-c000012/followers', 'api.localhost/groups/users/c42-c000013/followers', 'api.localhost/groups/users/c42-c000014/followers', 'api.localhost/groups/users/c42-c000015/followers', 'api.localhost/groups/users/c42-c000016/followers', 'api.localhost/groups/users/c42-c000017/followers', 'api.localhost/groups/users/c42-c000018/followers', 'api.localhost/groups/users/c42-c000019/followers')) WHERE rn = 1 AND deleted = 0) dg ON d.doc_id = dg.doc_id WHERE d.author_key NOT IN (SELECT user_key FROM (SELECT user_key, blocked_key, deleted, row_number() OVER (PARTITION BY user_key, blocked_key ORDER BY updated_at DESC, deleted DESC) AS rn FROM user_blacklist) WHERE rn = 1 AND deleted = 0 AND blocked_key = 'c42-reader') AND (d.author_key, dg.group_id) NOT IN (SELECT user_key, group_id FROM (SELECT user_key, group_id, blocked_key, deleted, row_number() OVER (PARTITION BY user_key, group_id, blocked_key ORDER BY updated_at DESC, deleted DESC) AS rn FROM group_blacklist) WHERE rn = 1 AND deleted = 0 AND blocked_key = 'c42-reader') AND NOT (d.author_key != 'c42-reader' AND (d.author_key, dg.group_id) IN (SELECT user_key, group_id FROM (SELECT user_key, group_id, sharing_enabled, deleted, row_number() OVER (PARTITION BY user_key, group_id ORDER BY updated_at DESC) AS rn FROM user_group_sharing) WHERE rn = 1 AND deleted = 0 AND sharing_enabled = 0)) AND (d.doc_id, dg.group_id) NOT IN (SELECT doc_id, group_id FROM (SELECT group_id, doc_id, deleted, row_number() OVER (PARTITION BY group_id, doc_id ORDER BY updated_at DESC, deleted DESC) AS rn FROM group_hidden_docs) WHERE rn = 1 AND deleted = 0) AND d.author_key NOT IN (SELECT username FROM (SELECT username, deleted, row_number() OVER (PARTITION BY username ORDER BY updated_at DESC, deleted DESC) AS rn FROM banned_users) WHERE rn = 1 AND deleted = 0)), profile AS (SELECT d.doc_id, d.author_key, d.posted_by, d.body, d.ref_value, d.tags, d.created_at, d.updated_at, d.ad_mode, d.ad_target, dg.group_id FROM (SELECT doc_id, author_key, posted_by, body, ref_value, tags, created_at, updated_at, ad_mode, ad_target FROM (SELECT doc_id, author_key, posted_by, body, ref_value, tags, created_at, updated_at, ad_mode, ad_target, deleted, row_number() OVER (PARTITION BY doc_id, author_key ORDER BY updated_at DESC) AS rn FROM documents WHERE collection_name = 'profile') WHERE rn = 1 AND deleted = 0) d JOIN (SELECT doc_id, group_id FROM (SELECT doc_id, group_id, deleted, row_number() OVER (PARTITION BY doc_id, group_id ORDER BY updated_at DESC) AS rn FROM doc_groups WHERE group_id IN ('api.localhost/groups/users/c42-c000000/followers', 'api.localhost/groups/users/c42-c000001/followers', 'api.localhost/groups/users/c42-c000002/followers', 'api.localhost/groups/users/c42-c000003/followers', 'api.localhost/groups/users/c42-c000004/followers', 'api.localhost/groups/users/c42-c000005/followers', 'api.localhost/groups/users/c42-c000006/followers', 'api.localhost/groups/users/c42-c000007/followers', 'api.localhost/groups/users/c42-c000008/followers', 'api.localhost/groups/users/c42-c000009/followers', 'api.localhost/groups/users/c42-c000010/followers', 'api.localhost/groups/users/c42-c000011/followers', 'api.localhost/groups/users/c42-c000012/followers', 'api.localhost/groups/users/c42-c000013/followers', 'api.localhost/groups/users/c42-c000014/followers', 'api.localhost/groups/users/c42-c000015/followers', 'api.localhost/groups/users/c42-c000016/followers', 'api.localhost/groups/users/c42-c000017/followers', 'api.localhost/groups/users/c42-c000018/followers', 'api.localhost/groups/users/c42-c000019/followers')) WHERE rn = 1 AND deleted = 0) dg ON d.doc_id = dg.doc_id WHERE d.author_key NOT IN (SELECT user_key FROM (SELECT user_key, blocked_key, deleted, row_number() OVER (PARTITION BY user_key, blocked_key ORDER BY updated_at DESC, deleted DESC) AS rn FROM user_blacklist) WHERE rn = 1 AND deleted = 0 AND blocked_key = 'c42-reader') AND (d.author_key, dg.group_id) NOT IN (SELECT user_key, group_id FROM (SELECT user_key, group_id, blocked_key, deleted, row_number() OVER (PARTITION BY user_key, group_id, blocked_key ORDER BY updated_at DESC, deleted DESC) AS rn FROM group_blacklist) WHERE rn = 1 AND deleted = 0 AND blocked_key = 'c42-reader') AND NOT (d.author_key != 'c42-reader' AND (d.author_key, dg.group_id) IN (SELECT user_key, group_id FROM (SELECT user_key, group_id, sharing_enabled, deleted, row_number() OVER (PARTITION BY user_key, group_id ORDER BY updated_at DESC) AS rn FROM user_group_sharing) WHERE rn = 1 AND deleted = 0 AND sharing_enabled = 0)) AND (d.doc_id, dg.group_id) NOT IN (SELECT doc_id, group_id FROM (SELECT group_id, doc_id, deleted, row_number() OVER (PARTITION BY group_id, doc_id ORDER BY updated_at DESC, deleted DESC) AS rn FROM group_hidden_docs) WHERE rn = 1 AND deleted = 0) AND d.author_key NOT IN (SELECT username FROM (SELECT username, deleted, row_number() OVER (PARTITION BY username ORDER BY updated_at DESC, deleted DESC) AS rn FROM banned_users) WHERE rn = 1 AND deleted = 0)), reactions AS (SELECT d.doc_id, d.author_key, d.posted_by, d.body, d.ref_value, d.tags, d.created_at, d.updated_at, d.ad_mode, d.ad_target, dg.group_id FROM (SELECT doc_id, author_key, posted_by, body, ref_value, tags, created_at, updated_at, ad_mode, ad_target FROM (SELECT doc_id, author_key, posted_by, body, ref_value, tags, created_at, updated_at, ad_mode, ad_target, deleted, row_number() OVER (PARTITION BY doc_id, author_key ORDER BY updated_at DESC) AS rn FROM documents WHERE collection_name = 'reactions') WHERE rn = 1 AND deleted = 0) d JOIN (SELECT doc_id, group_id FROM (SELECT doc_id, group_id, deleted, row_number() OVER (PARTITION BY doc_id, group_id ORDER BY updated_at DESC) AS rn FROM doc_groups WHERE group_id IN ('api.localhost/groups/users/c42-c000000/followers', 'api.localhost/groups/users/c42-c000001/followers', 'api.localhost/groups/users/c42-c000002/followers', 'api.localhost/groups/users/c42-c000003/followers', 'api.localhost/groups/users/c42-c000004/followers', 'api.localhost/groups/users/c42-c000005/followers', 'api.localhost/groups/users/c42-c000006/followers', 'api.localhost/groups/users/c42-c000007/followers', 'api.localhost/groups/users/c42-c000008/followers', 'api.localhost/groups/users/c42-c000009/followers', 'api.localhost/groups/users/c42-c000010/followers', 'api.localhost/groups/users/c42-c000011/followers', 'api.localhost/groups/users/c42-c000012/followers', 'api.localhost/groups/users/c42-c000013/followers', 'api.localhost/groups/users/c42-c000014/followers', 'api.localhost/groups/users/c42-c000015/followers', 'api.localhost/groups/users/c42-c000016/followers', 'api.localhost/groups/users/c42-c000017/followers', 'api.localhost/groups/users/c42-c000018/followers', 'api.localhost/groups/users/c42-c000019/followers')) WHERE rn = 1 AND deleted = 0) dg ON d.doc_id = dg.doc_id WHERE d.author_key NOT IN (SELECT user_key FROM (SELECT user_key, blocked_key, deleted, row_number() OVER (PARTITION BY user_key, blocked_key ORDER BY updated_at DESC, deleted DESC) AS rn FROM user_blacklist) WHERE rn = 1 AND deleted = 0 AND blocked_key = 'c42-reader') AND (d.author_key, dg.group_id) NOT IN (SELECT user_key, group_id FROM (SELECT user_key, group_id, blocked_key, deleted, row_number() OVER (PARTITION BY user_key, group_id, blocked_key ORDER BY updated_at DESC, deleted DESC) AS rn FROM group_blacklist) WHERE rn = 1 AND deleted = 0 AND blocked_key = 'c42-reader') AND NOT (d.author_key != 'c42-reader' AND (d.author_key, dg.group_id) IN (SELECT user_key, group_id FROM (SELECT user_key, group_id, sharing_enabled, deleted, row_number() OVER (PARTITION BY user_key, group_id ORDER BY updated_at DESC) AS rn FROM user_group_sharing) WHERE rn = 1 AND deleted = 0 AND sharing_enabled = 0)) AND (d.doc_id, dg.group_id) NOT IN (SELECT doc_id, group_id FROM (SELECT group_id, doc_id, deleted, row_number() OVER (PARTITION BY group_id, doc_id ORDER BY updated_at DESC, deleted DESC) AS rn FROM group_hidden_docs) WHERE rn = 1 AND deleted = 0) AND d.author_key NOT IN (SELECT username FROM (SELECT username, deleted, row_number() OVER (PARTITION BY username ORDER BY updated_at DESC, deleted DESC) AS rn FROM banned_users) WHERE rn = 1 AND deleted = 0)) SELECT p.doc_id AS doc_id, p.author_key AS author_key, p.posted_by AS posted_by, p.group_id AS group_id, p.body AS body, p.tags AS tags, p.created_at AS created_at, p.ref_value AS ref_value, p.ad_mode AS ad_mode, p.ad_target AS ad_target, coalesce(eng.like_count, 0) AS likes, coalesce(eng.dislike_count, 0) AS dislikes, coalesce(rp.repost_count, 0) AS reposts, coalesce(cmt.comment_count, 0) AS comments, (0) AS score, pr.body AS profile_body FROM posts AS p LEFT JOIN (SELECT ref_value, countIf(JSONExtractString(body, 'type') = 'like') AS like_count, countIf(JSONExtractString(body, 'type') = 'dislike') AS dislike_count FROM reactions WHERE ref_value <> '' GROUP BY ref_value) AS eng ON eng.ref_value = p.doc_id LEFT JOIN (SELECT JSONExtractString(body, 'repost_of') AS repost_of, count() AS repost_count FROM posts WHERE JSONExtractString(body, 'repost_of') <> '' GROUP BY repost_of) AS rp ON rp.repost_of = p.doc_id LEFT JOIN (SELECT JSONExtractString(body, 'post_id') AS post_id, count() AS comment_count FROM comments WHERE JSONExtractString(body, 'post_id') <> '' GROUP BY post_id) AS cmt ON cmt.post_id = p.doc_id LEFT JOIN (SELECT author_key, body FROM profile QUALIFY row_number() OVER (PARTITION BY author_key ORDER BY updated_at DESC) = 1) AS pr ON pr.author_key = p.author_key WHERE NOT has(p.tags, 'ad') AND NOT has(p.tags, 'product') ORDER BY toUnixTimestamp64Milli(p.created_at) DESC LIMIT 21
